def evaluate_expression(expression):
    # Helper function to evaluate a single expression
    def evaluate(expr):
        if isinstance(expr, int):
            return expr
        left, op, right = expr
        if op == '+':
            return evaluate(left) + evaluate(right)
        elif op == '-':
            return evaluate(left) - evaluate(right)

    # Convert the expression into a list of operations and numbers
    stack = []
    num_str = ''
    for char in expression:
        if char.isdigit():
            num_str += char
        else:
            if num_str:
                stack.append(int(num_str))
                num_str = ''
            if char == '?':
                stack.append(char)
            elif char in '+-':
                stack.append(char)

    if num_str:
        stack.append(int(num_str))

    # Convert the list into a tree-like structure
    def parse_expression(tokens):
        if len(tokens) == 1:
            return tokens[0]
        for i in range(len(tokens)):
            if isinstance(tokens[i], str) and tokens[i] in '+-':
                left = parse_expression(tokens[:i])
                right = parse_expression(tokens[i+1:])
                return (left, tokens[i], right)
        return None

    return parse_expression(stack)

def insert_operators(expression, plus_count, minus_count):
    from itertools import product

    # Generate all possible combinations of '+' and '-'
    operators = ['+'] * plus_count + ['-'] * minus_count
    operator_combinations = set(product(operators, repeat=expression.count('?')))

    max_value = float('-inf')

    # Evaluate each possible expression
    for combination in operator_combinations:
        temp_expression = list(expression)
        operator_index = 0
        for i in range(len(temp_expression)):
            if temp_expression[i] == '?':
                temp_expression[i] = combination[operator_index]
                operator_index += 1
        evaluated_value = evaluate_expression(temp_expression)
        max_value = max(max_value, evaluated_value)

    return max_value

